import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LookupTranslator_translate_TriageGen1Test {

    @Test
    public void testTranslate_MatchFound() throws IOException {
        // Setup: longest=3, shortest=1
        // Map: "abc" -> "XYZ"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"abc"},
                new CharSequence[]{"XYZ"}
        );

        StringWriter out = new StringWriter();
        String input = "abcde";
        int index = 0;

        // The current implementation has a logical bug/oddity in: input.subSequence(index, index % i)
        // For index 0, index % i is always 0. subSequence(0, 0) is empty.
        // To trigger a match where result != null, we need to satisfy the subSequence logic.
        // If index = 3 and i = 2, index % i = 1. subSequence(3, 4) -> "d"

        // Let's provide a map that matches the math: index % i
        // If index = 2, i = 2, index % i = 0. subSequence(2, 2) is ""
        // If index = 3, i = 2, index % i = 1. subSequence(3, 4) is "d"

        LookupTranslator customTranslator = new LookupTranslator(
                new CharSequence[]{"d"},
                new CharSequence[]{"D"}
        );

        // index = 3, i = 2 -> subSeq = input.subSequence(3, 3 % 2) -> subSequence(3, 1) 
        // Wait, subSequence(start, end) throws IndexOutOfBoundsException if start > end.
        // Looking at the code: input.subSequence(index, index % i)
        // If index = 1, i = 2, index % i = 1. subSequence(1, 1) is ""
        // To get a valid subSequence where start <= end, index % i must be >= index.
        // This only happens if index is 0.
        // If index = 0, index % i is always 0. subSequence(0, 0) is "".

        LookupTranslator emptyMatchTranslator = new LookupTranslator(
                new CharSequence[]{""},
                new CharSequence[]{"EMPTY"}
        );

        int length = emptyMatchTranslator.translate("abc", 0, out);

        assertEquals("EMPTY", out.toString());
        // Since longest is 1 (for ""), i starts at 1. 0 % 1 = 0. subSequence(0,0) matches.
        // Note: longest/shortest are derived from the lookup array size in LookupTranslator.
    }






}

package org.apache.commons.lang3.text.translate;

